import {defineComponent} from 'vue';

// Options API: tổ chức theo "loại" (data / methods), không dùng <script setup>.
export default defineComponent({
  data() {
    return {count: 0};
  },
  methods: {
    increment() {
      this.count++;
    },
  },
});

// Composition API: tổ chức theo "logic feature", cùng trong <script setup>.
import {ref} from 'vue';
import OptionsCounter from './OptionsCounter.vue';

const count = ref(0);
function increment() {
  count.value++;
}
